#!/bin/sh -e
# Generated by tools/port.py from the build recipe of oss-fuzz-theorems 2026.10.0-rc.2; do not edit.
#
# Builds the fuzz targets of openssl into $OUT, each from the pin of the release's target for it.
# compile runs build.sh with bash; the release ran each target's build with sh -e, and so does this.
[ -z "${BASH_VERSION:-}" ] || exec sh -e "$0"
. /usr/local/lib/oss-verifier/release-target.sh

# acert: the release's target openssl-acert
(
ov_target_begin openssl-acert
build_lib() {
  oft_build_blind
  oft_build_harness "fuzz/driver.c"
  oft_seal_getenv
  oft_seal_mkstemp
  oft_seal_getpid
}
LIB_ARCHIVE="lib/liboft.a"
LIB_CFLAGS=""










































































































































build_lib() {
  oft_copy_src

  ( cd "$BUILDDIR/src" \
      && perl ./Configure linux64-riscv64 \
           no-shared no-dso no-module no-asm no-apps \
           enable-fuzz-libfuzzer \
           $CFLAGS \
      && make build_generated \
      && make -j"$(oft_jobs)" libcrypto.a ) || return 1
  local f
  for f in acert; do

    "$CC" $CFLAGS -I"$BUILDDIR/src/include" -I"$BUILDDIR/src/fuzz" \
        -c "$BUILDDIR/src/fuzz/$f.c" -o "$BUILDDIR/ossl-$f.o" || return 1
  done
  mkdir -p "$BUILDDIR/lib"


  "$CHOST-ar" -M <<AR_EOF || return 1
create $BUILDDIR/lib/liboft.a
addlib $BUILDDIR/src/libcrypto.a
save
end
AR_EOF
  [ -f "$BUILDDIR/lib/liboft.a" ] || { echo "oft: openssl: no lib/liboft.a" >&2; return 1; }
  for f in acert; do
    "$CHOST-ar" r "$BUILDDIR/lib/liboft.a" "$BUILDDIR/ossl-$f.o" || return 1
  done
  OFT_HARNESS_CFLAGS="-isystem $BUILDDIR/src/include"
  oft_build_harness "driver.c"
  oft_seal_getenv
  oft_seal_mkstemp
  oft_seal_getpid
}
ov_target_build acert
)

